package br.com.oficina.infrastructure;

import io.jsonwebtoken.*; import io.jsonwebtoken.security.Keys;
import org.springframework.security.authentication.dao.DaoAuthenticationProvider;
import jakarta.servlet.*; import jakarta.servlet.http.*;
import org.springframework.beans.factory.annotation.Value; import org.springframework.context.annotation.*; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.core.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.core.userdetails.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.stereotype.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.filter.OncePerRequestFilter;
import javax.crypto.SecretKey; import java.io.IOException; import java.nio.charset.StandardCharsets; import java.time.*; import java.util.*;

@Configuration @EnableWebSecurity class SecurityConfiguration {
 @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder();}
 @Bean UserDetailsService users(PasswordEncoder p){return username-> {if("admin".equals(username))return new org.springframework.security.core.userdetails.User("admin",p.encode("admin123"),List.of(new SimpleGrantedAuthority("ROLE_ADMIN")));throw new UsernameNotFoundException(username);};}
 @Bean AuthenticationManager authenticationManager(UserDetailsService u,PasswordEncoder p){return new ProviderManager(new DaoAuthenticationProvider(){{setUserDetailsService(u);setPasswordEncoder(p);}});}
 @Bean SecurityFilterChain filterChain(HttpSecurity h,JwtFilter f)throws Exception{return h.csrf(c->c.disable()).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/api/auth/**","/api/public/**","/h2-console/**").permitAll().anyRequest().authenticated()).headers(x->x.frameOptions(y->y.sameOrigin())).addFilterBefore(f,UsernamePasswordAuthenticationFilter.class).build();}
}
@Service class JwtService { private final SecretKey key; private final Duration expiration; JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.expiration-minutes}")long minutes){key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));expiration=Duration.ofMinutes(minutes);} String gerar(String usuario){Instant now=Instant.now();return Jwts.builder().subject(usuario).issuedAt(Date.from(now)).expiration(Date.from(now.plus(expiration))).signWith(key).compact();} String usuario(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload().getSubject();} }
@Component class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; JwtFilter(JwtService j){jwt=j;} @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String u=jwt.usuario(h.substring(7));SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u,null,List.of(new SimpleGrantedAuthority("ROLE_ADMIN"))));}catch(JwtException ignored){}c.doFilter(r,s);} }
@RestController @RequestMapping("/api/auth") class AuthController { private final AuthenticationManager auth; private final JwtService jwt; AuthController(AuthenticationManager a,JwtService j){auth=a;jwt=j;} @PostMapping("/login") Map<String,String> login(@RequestBody Credenciais c){auth.authenticate(new UsernamePasswordAuthenticationToken(c.usuario(),c.senha()));return Map.of("token",jwt.gerar(c.usuario()),"tipo","Bearer");} record Credenciais(String usuario,String senha){} }
